const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  var startDate = '2005-07-12';
  var endDate = '2005-07-20'; // exclusive

  // Get state boundaries
  var states = ee.FeatureCollection('TIGER/2018/States');
  var california = states.filter(ee.Filter.eq('NAME', 'California'));
  var mississippi = states.filter(ee.Filter.eq('NAME', 'Mississippi'));

  var californiaGeom = california.geometry();
  var mississippiGeom = mississippi.geometry();

  // 2. Data Acquisition - MODIS Land Surface Temperature
  var modisLST = ee.ImageCollection('MODIS/006/MOD11A2')
    .filterDate(startDate, endDate)
    .select(['LST_Day_1km', 'QC_Day']);

  // Check if collection has data
  var collectionSize = modisLST.size().getInfo();
  if (collectionSize === 0) {
    console.log("No MODIS LST data found for the period.");
    console.log("<answer>C1</answer>");
    return;
  }

  // Get the single 8-day composite image
  var lstImage = modisLST.first();

  // 3. Quality Masking
  // Extract QC band and create mask (bits 0-1: 00 = good quality)
  var qcDay = lstImage.select('QC_Day');
  var mask = qcDay.bitwiseAnd(3).eq(0); // bits 0-1 = 00

  // Apply mask and convert LST from Kelvin to Celsius
  var lstDay = lstImage.select('LST_Day_1km')
    .updateMask(mask)
    .multiply(0.02)  // Scale factor for MODIS LST
    .subtract(273.15); // Convert K to °C

  // 4. Calculate mean LST for each state
  var californiaStats = lstDay.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: californiaGeom,
    scale: 1000,
    maxPixels: 1e9
  });

  var mississippiStats = lstDay.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: mississippiGeom,
    scale: 1000,
    maxPixels: 1e9
  });

  // Also count valid pixels to check for C2
  var californiaCount = lstDay.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: californiaGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  var mississippiCount = lstDay.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: mississippiGeom,
    scale: 1000,
    maxPixels: 1e9
  }).get('LST_Day_1km');

  // Get values
  var caTemp = californiaStats.get('LST_Day_1km').getInfo();
  var msTemp = mississippiStats.get('LST_Day_1km').getInfo();
  var caCount = californiaCount.getInfo();
  var msCount = mississippiCount.getInfo();

  // 5. Validation & Final Answer
  console.log(`California: ${caCount} valid pixels, Mean LST: ${caTemp !== null ? caTemp.toFixed(2) + '°C' : 'null'}`);
  console.log(`Mississippi: ${msCount} valid pixels, Mean LST: ${msTemp !== null ? msTemp.toFixed(2) + '°C' : 'null'}`);

  // Check for no valid pixels (C2)
  if (caCount === 0 || msCount === 0) {
    console.log("One or both states have no valid pixels after masking.");
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failure (C3)
  if (caTemp === null || msTemp === null || 
      isNaN(caTemp) || isNaN(msTemp) ||
      caTemp < -100 || caTemp > 100 ||  // Valid LST range check
      msTemp < -100 || msTemp > 100) {
    console.log("Invalid temperature values calculated.");
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare temperatures
  if (caTemp > msTemp) {
    console.log(`California LST (${caTemp.toFixed(2)}°C) > Mississippi LST (${msTemp.toFixed(2)}°C)`);
    console.log("<answer>A</answer>");
  } else {
    console.log(`California LST (${caTemp.toFixed(2)}°C) <= Mississippi LST (${msTemp.toFixed(2)}°C)`);
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
